//! The IPC protocol against the prototype's recording `tests/fixtures/ipc.json` (generated by
//! `scripts/golden/agent_ipc_fixtures.py`; CTR-01):
//!
//! - `server`: every conversation is replayed against the Rust server, and its replies must equal
//!   the prototype's byte for byte (Python's `json.dumps` layout included). The `pong` time
//!   differs by nature and is masked on both sides. The recording speaks API 1.0, this build
//!   1.1 (CTR-01): a reply that carries the API version or the tools (`hello`, `info`,
//!   `tools/list`, an unknown tool's `available` list) is compared as its 1.0 view, which takes
//!   out exactly the recorded additions (`contract::versions`). Deliberate divergences are
//!   compared with their documented Rust result.
//! - `client`: the Rust client runs every scenario against the same scripted server, and must
//!   send the prototype client's request lines byte for byte and reach its outcomes: the result,
//!   or the error's code, message and details.
#![cfg(unix)]

use std::fs;
use std::io::{self, BufRead, BufReader, Write};
use std::net::Shutdown;
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::thread::{self, JoinHandle};
use std::time::Duration;

use serde_json::{Value, json};
use sonara_agent::context::PolicyEnvironment;
use sonara_agent::contract::TOOLS;
use sonara_agent::contract::versions::{is_added_tool, recorded_view};
use sonara_agent::ipc::{
    ClientContext, ClientOptions, DEFAULT_TIMEOUT, Discovery, IpcClient, IpcServer, MAX_MESSAGE,
    ServerOptions, Transport,
};
use sonara_agent::registry::error_json;
use sonara_agent::service::{AgentOptions, AgentService, AuditTarget};
use sonara_app::context::{AppContext, AppOptions};
use sonara_app::settings::Settings;

const TOKEN: &str = "{TOKEN}";

fn fixture() -> Value {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/ipc.json");
    serde_json::from_str(&fs::read_to_string(path).expect("the fixture")).expect("JSON")
}

fn text(value: &Value) -> &str {
    value.as_str().expect("a string")
}

// -- server -------------------------------------------------------------------------------------

/// Replays one conversation as the recorder ran it: the replies (without newlines) and whether
/// the server closed the connection.
fn converse(address: &str, token: &str, send: &[Value]) -> (Vec<String>, bool) {
    let stream = UnixStream::connect(address).expect("connects");
    stream
        .set_read_timeout(Some(Duration::from_secs(10)))
        .expect("a timeout");
    let mut reader = BufReader::new(stream.try_clone().expect("cloned"));
    let mut writer = stream;
    let mut receive = Vec::new();
    let mut read_reply = |reader: &mut BufReader<UnixStream>| {
        let mut line = Vec::new();
        match reader.read_until(b'\n', &mut line) {
            Ok(_) => {}
            // Linux resets a Unix domain socket that was closed with unread data.
            Err(error) if error.kind() == io::ErrorKind::ConnectionReset => return false,
            Err(error) => panic!("cannot read a reply: {error}"),
        }
        if line.is_empty() {
            return false;
        }
        assert_eq!(line.pop(), Some(b'\n'), "a complete line");
        receive.push(String::from_utf8(line).expect("ASCII"));
        true
    };
    let mut closed = false;
    for item in send {
        if item.get("eof").is_some() {
            writer.shutdown(Shutdown::Write).expect("shut down");
            while read_reply(&mut reader) {}
            closed = true;
            break;
        }
        let data = if let Some(line) = item.get("line") {
            format!("{}\n", text(line).replace(TOKEN, token)).into_bytes()
        } else if let Some(bytes) = item.get("bytes") {
            let bytes = hex(text(bytes));
            match String::from_utf8(bytes) {
                Ok(text) => text.replace(TOKEN, token).into_bytes(),
                Err(error) => error.into_bytes(),
            }
        } else {
            let count = usize::try_from(item["filler"].as_u64().expect("a count")).expect("fits");
            let mut filler = vec![b'a'; count];
            filler.push(b'\n');
            filler
        };
        if let Err(error) = writer.write_all(&data) {
            // The server closed the connection. Which error the write sees depends on timing;
            // macOS also reports a socket whose peer has fully shut down as not connected.
            assert!(
                matches!(
                    error.kind(),
                    io::ErrorKind::BrokenPipe
                        | io::ErrorKind::ConnectionReset
                        | io::ErrorKind::NotConnected
                ),
                "{error}"
            );
            closed = true;
            break;
        }
        if item.get("reply") != Some(&Value::Bool(false)) && !read_reply(&mut reader) {
            closed = true;
            break;
        }
    }
    if !closed {
        reader
            .get_ref()
            .set_read_timeout(Some(Duration::from_millis(300)))
            .expect("a timeout");
        let mut extra = Vec::new();
        match reader.read_until(b'\n', &mut extra) {
            Ok(_) => {
                assert!(
                    extra.is_empty(),
                    "unexpected {}",
                    String::from_utf8_lossy(&extra)
                );
                closed = true;
            }
            Err(error) if error.kind() == io::ErrorKind::ConnectionReset => closed = true,
            Err(error) => assert!(
                matches!(
                    error.kind(),
                    io::ErrorKind::WouldBlock | io::ErrorKind::TimedOut
                ),
                "{error}"
            ),
        }
    }
    (receive, closed)
}

fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hexadecimal"))
        .collect()
}

/// The parsed reply when it carries a value that differs by nature (the `pong` time, masked
/// here) or by API version (the version, the tool count, the tool lists); `None` for a reply
/// that compares byte for byte.
fn comparable(line: &str) -> Option<Value> {
    let mut value: Value = serde_json::from_str(line).ok()?;
    let mut changed = value.pointer("/result/error/details/available").is_some();
    if let Some(result) = value.get_mut("result").and_then(Value::as_object_mut) {
        if result.get("pong").is_some_and(Value::is_number) {
            result.insert("pong".to_owned(), json!(0.0));
            changed = true;
        }
        changed |= result.contains_key("api_version") || result.contains_key("tools");
    }
    changed.then_some(value)
}

/// What API 1.0 answers in place of `reply`, a parsed reply of this build: the 1.0 view of a
/// `hello`, `info` or `tools/list` result, and an unknown tool's `available` list without the
/// added tools. Anything else stays, so the view equals the recording only when the reply
/// differs from it by exactly the recorded additions.
fn recorded(mut reply: Value) -> Value {
    if let Some(Value::Array(available)) = reply.pointer_mut("/result/error/details/available") {
        available.retain(|name| !name.as_str().is_some_and(is_added_tool));
    }
    if let Some(result) = reply.get_mut("result")
        && (result.get("api_version").is_some() || result.get("tools").is_some())
    {
        *result = recorded_view(result);
    }
    reply
}

struct Running {
    _dir: tempfile::TempDir,
    _app: Arc<AppContext>,
    agent: Arc<AgentService>,
    server: IpcServer,
}

fn server() -> Running {
    let dir = tempfile::tempdir().expect("a temporary directory");
    let root = fs::canonicalize(dir.path()).expect("resolves");
    let app = Arc::new(
        AppContext::create(AppOptions {
            workspaces: Some(root.join("workspaces")),
            settings: Some(Settings::default()),
            persist_settings: false,
            audio_backend: Some("null".to_owned()),
            ..AppOptions::default()
        })
        .expect("the application"),
    );
    let agent = Arc::new(
        AgentService::new(
            Arc::clone(&app),
            AgentOptions {
                base_dir: Some(root.clone()),
                source: "ipc".to_owned(),
                audit: AuditTarget::Disabled,
                environment: Some(PolicyEnvironment {
                    allowed: None,
                    projects_dir: root.join("projects"),
                }),
                ..AgentOptions::default()
            },
        )
        .expect("the agent"),
    );
    let server = IpcServer::start(
        Arc::clone(&agent),
        ServerOptions {
            app_kind: "test".to_owned(),
            directory: Some(root.join("run")),
        },
    )
    .expect("the server");
    Running {
        _dir: dir,
        _app: app,
        agent,
        server,
    }
}

#[test]
fn server_answers_like_the_prototype() {
    let fixture = fixture();
    assert_eq!(fixture["protocol"], 1);
    assert_eq!(fixture["max_message"], MAX_MESSAGE);
    let Running { agent, server, .. } = &server();
    // Every tool of the contract has a handler, so the tool lists and counts compare whole.
    assert_eq!(agent.tools().len(), TOOLS.len());
    let mut checked = 0;
    for conversation in fixture["server"].as_array().expect("conversations") {
        let name = text(&conversation["name"]);
        let expected = conversation.get("rust").unwrap_or(conversation);
        let send = conversation["send"].as_array().expect("items");
        let (receive, closed) = converse(server.address(), server.token(), send);
        let wanted: Vec<&str> = expected["receive"]
            .as_array()
            .expect("lines")
            .iter()
            .map(text)
            .collect();
        assert_eq!(receive.len(), wanted.len(), "{name}: {receive:#?}");
        for (i, (actual, wanted)) in receive.iter().zip(&wanted).enumerate() {
            match comparable(wanted) {
                None => assert_eq!(actual, wanted, "{name}, line {i}"),
                Some(wanted) => {
                    let actual = recorded(comparable(actual).expect("the same fields"));
                    if wanted["result"]["tools"].is_array() {
                        // The tool contract writes each schema's keywords in another order
                        // than pydantic (`type` first rather than sorted); its golden test
                        // compares canonical JSON. Here the values must be equal.
                        assert_eq!(actual, wanted, "{name}, line {i}");
                    } else {
                        // Compared as text, so that the key order counts too.
                        assert_eq!(actual.to_string(), wanted.to_string(), "{name}, line {i}");
                    }
                }
            }
        }
        assert_eq!(closed, expected["closed"], "{name}: closed");
        checked += 1;
    }
    assert!(checked >= 70, "{checked} conversations");
}

// -- client -------------------------------------------------------------------------------------

/// The scripted server of the recorder: answers each request line as the script says and
/// returns the lines it read.
fn scripted(path: &Path, script: Vec<Value>) -> JoinHandle<Vec<String>> {
    let listener = UnixListener::bind(path).expect("binds");
    thread::spawn(move || {
        let (stream, _) = listener.accept().expect("a client");
        let mut reader = BufReader::new(stream.try_clone().expect("cloned"));
        let mut writer = stream;
        let mut requests = Vec::new();
        let mut read = |reader: &mut BufReader<UnixStream>| {
            let mut line = Vec::new();
            reader.read_until(b'\n', &mut line).expect("a request");
            if line.is_empty() {
                return false;
            }
            assert_eq!(line.pop(), Some(b'\n'), "a complete line");
            requests.push(String::from_utf8(line).expect("ASCII"));
            true
        };
        let mut sending = true;
        for action in &script {
            if !read(&mut reader) {
                return requests;
            }
            if let Some(delay) = action.get("delay").and_then(Value::as_f64) {
                thread::sleep(Duration::from_secs_f64(delay));
            }
            if action.get("close").is_some() {
                return requests;
            }
            if let Some(reply) = action.get("reply").filter(|_| sending) {
                sending = writer
                    .write_all(format!("{}\n", text(reply)).as_bytes())
                    .is_ok();
            }
        }
        while read(&mut reader) {}
        requests
    })
}

fn client_options(options: Option<&Value>) -> ClientOptions {
    let mut out = ClientOptions::default();
    let Some(options) = options else {
        return out;
    };
    if let Some(client) = options.get("client") {
        text(client).clone_into(&mut out.client);
    }
    if let Some(context) = options.get("context") {
        out.context = Some(ClientContext {
            base_dir: context["base_dir"].as_str().map(PathBuf::from),
            allowed_paths: context["allowed_paths"]
                .as_array()
                .expect("paths")
                .iter()
                .map(|path| PathBuf::from(text(path)))
                .collect(),
        });
    }
    out.timeout = options
        .get("timeout")
        .and_then(Value::as_f64)
        .map_or(DEFAULT_TIMEOUT, Duration::from_secs_f64);
    out
}

fn outcome<T: Into<Value>>(result: Result<T, sonara_agent::ipc::ClientError>) -> Value {
    match result {
        Ok(value) => json!({"ok": value.into()}),
        Err(error) => json!({"error": error_json(&error.to_domain())}),
    }
}

#[test]
fn client_behaves_like_the_prototype() {
    let fixture = fixture();
    for scenario in fixture["client"].as_array().expect("scenarios") {
        let name = text(&scenario["name"]);
        let dir = tempfile::tempdir().expect("a temporary directory");
        let path = dir.path().join("s.sock");
        let address = path.to_str().expect("UTF-8").to_owned();
        let fake = scenario
            .get("script")
            .map(|script| scripted(&path, script.as_array().expect("actions").clone()));
        let discovery = Discovery {
            pid: i64::from(std::process::id()),
            transport: Transport::Unix,
            address: address.clone(),
            token: "tok-123".to_owned(),
            protocol: 1,
            app: "fake".to_owned(),
            started: 0.0,
            path: dir.path().join("session-0.json"),
        };
        let mut outcomes = Vec::new();
        match IpcClient::connect(discovery, &client_options(scenario.get("options"))) {
            Err(error) => outcomes.push(outcome::<Value>(Err(error))),
            Ok(client) => {
                outcomes.push(json!({"ok": client.server_info()}));
                for step in scenario["steps"].as_array().expect("steps") {
                    outcomes.push(match text(&step["op"]) {
                        "call" => outcome(client.call(text(&step["name"]), step.get("arguments"))),
                        "tools" => outcome(client.tools()),
                        _ => outcome(client.ping()),
                    });
                }
            }
        }
        let requests = fake
            .map(|fake| fake.join().expect("the scripted server"))
            .unwrap_or_default();
        let wanted: Vec<&str> = scenario["requests"]
            .as_array()
            .expect("lines")
            .iter()
            .map(text)
            .collect();
        assert_eq!(requests, wanted, "{name}: requests");
        let expected = scenario
            .get("outcomes_rust")
            .unwrap_or(&scenario["outcomes"]);
        let actual = Value::Array(outcomes)
            .to_string()
            .replace(&address, "<ADDR>");
        assert_eq!(actual, expected.to_string(), "{name}: outcomes");
    }
}
